{
  "items": [
    {
      "name": "finsum_def'",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {M : Type u_7} {α : Sort u_8} [inst : AddCommMonoid M] (f : α → M),\n  finsum f = if h : (Function.support (f ∘ PLift.down)).Finite then ∑ i ∈ h.toFinset, f i.down else 0"
    },
    {
      "name": "finsum_mem_eq_sum",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} [inst : AddCommMonoid M] (f : α → M) {s : Set α} (hf : (s ∩ Function.support f).Finite),\n  ∑ᶠ (i : α) (_ : i ∈ s), f i = ∑ i ∈ hf.toFinset, f i"
    },
    {
      "name": "Finsupp.sum_fintype",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] [inst_2 : Fintype α]\n  (f : α →₀ M) (g : α → M → N), (∀ (i : α), g i 0 = 0) → f.sum g = ∑ i, g i (f i)"
    },
    {
      "name": "finsum",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "definition",
      "type": "{M : Type u_7} → {α : Sort u_8} → [AddCommMonoid M] → (α → M) → M"
    },
    {
      "name": "Fintype.sum_subset",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {M : Type u_4} {ι : Type u_7} [inst : Fintype ι] [inst_1 : AddCommMonoid M] {s : Finset ι} {f : ι → M},\n  (∀ (i : ι), f i ≠ 0 → i ∈ s) → ∑ i ∈ s, f i = ∑ i, f i"
    },
    {
      "name": "Finsupp.sum_of_support_subset",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] (f : α →₀ M) {s : Finset α},\n  f.support ⊆ s → ∀ (g : α → M → N), (∀ i ∈ s, g i 0 = 0) → f.sum g = ∑ x ∈ s, g x (f x)"
    },
    {
      "name": "Finsupp.onFinset_sum",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] {s : Finset α} {f : α → M}\n  {g : α → M → N} (hf : ∀ (a : α), f a ≠ 0 → a ∈ s),\n  (∀ (a : α), g a 0 = 0) → (Finsupp.onFinset s f hf).sum g = ∑ a ∈ s, g a (f a)"
    },
    {
      "name": "tsum_eq_sum'",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : AddCommMonoid α] [inst_1 : TopologicalSpace α] {f : β → α}\n  {L : SummationFilter β} [L.LeAtTop] {s : Finset β}, Function.support f ⊆ ↑s → ∑'[L] (b : β), f b = ∑ b ∈ s, f b"
    }
  ]
}

