∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] {s : Finset α} {f : α → M}
  {g : α → M → N} (hf : ∀ (a : α), f a ≠ 0 → a ∈ s),
  (∀ (a : α), g a 0 = 0) → (Finsupp.onFinset s f hf).sum g = ∑ a ∈ s, g a (f a)
